using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace TenantPortal.Domain.Entities
{
    [Table("Agreements", Schema = "dbo")]
    public class Agreement
    {
        [Key]
        public Guid AgreementId { get; set; }

        // Legacy/unused column on the live table — never populated.
        public Guid? ContractId { get; set; }

        // Admin Manual (20-10-2026) §2.4: auto-generated by the system
        // (e.g. "AGR-000001") — the real identifier now, replacing
        // ContractNumber in that role. ContractNumber survives as the
        // optional "Agreement Reference" field below.
        [Required, MaxLength(50)]
        public string AgreementNo { get; set; } = default!;

        // Was "Contract ID" (required+unique, the primary identifier) —
        // now an optional external reference per the updated manual.
        // Admin Manual (25-10-2026) §2.4 Agreement Detail: "80 Charter Text
        // filed" — widened from 50.
        [MaxLength(80)]
        public string? ContractNumber { get; set; }

        public Guid TenantId { get; set; }

        // Admin Manual (20-10-2026) §2.4: Agreement is vendor-specific —
        // one Agreement per vendor per tenant.
        public Guid VendorId { get; set; }

        [Required, MaxLength(50)]
        public string ContractType { get; set; } = default!;

        public DateTime StartDate { get; set; }
        public DateTime EndDate { get; set; }

        public bool AutoRenewal { get; set; }

        // Required only when AutoRenewal is true (enforced in the service).
        public int? RenewalNoticeDays { get; set; }

        [Required, MaxLength(50)]
        public string PaymentTerm { get; set; } = default!;

        [MaxLength(10)]
        public string? Currency { get; set; } // ISO code, FK to Currency.isocode

        public Guid? CountryId { get; set; }

        // Admin Manual (25-10-2026) §2.4: auto-populated server-side from
        // CountryId's Region (see AgreementsService) — read-only to the client.
        public Guid? RegionId { get; set; }

        [MaxLength(150)]
        public string? ContactName { get; set; }

        [Required, MaxLength(150)]
        public string Email { get; set; } = default!;

        [MaxLength(50)]
        public string? ContactNumber { get; set; }

        // "Value has to be pick from Tenant" — server-set from the Tenant's
        // own Domain, not client-supplied (see AgreementsService).
        [MaxLength(150)]
        public string? DomainName { get; set; }

        [Required, MaxLength(255)]
        public string DocumentPath { get; set; } = default!;

        // Distinct from Notes: "200 Charter Text filed" customer-facing
        // field vs. Notes' longer internal-only free text.
        [MaxLength(200)]
        public string? Remark { get; set; }

        [MaxLength(2000)]
        public string? Notes { get; set; }

        [Required]
        public AgreementStatus Status { get; set; } = AgreementStatus.PendingApproval;

        public Guid CreatedBy { get; set; }
        public DateTime CreatedAt { get; set; }
    }
}
